import React, { useState, useEffect } from 'react';
import { Table, Button, Space, Modal, Form, Input, DatePicker, message, Drawer, Select, Tag, Grid, List, Typography } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, FilterOutlined, SettingOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import isoWeek from 'dayjs/plugin/isoWeek';
import { useAuth } from '../AuthContext';
import { resizableTableComponents, useResizableColumns } from '../components/ResizableTable';
import { RichTextEditor, RichTextView, richTextToPlain } from '../components/RichText';

dayjs.extend(isoWeek);

const { TextArea } = Input;
const { Option } = Select;
const { RangePicker } = DatePicker;
const { useBreakpoint } = Grid;

const ADMIN_ROLES = new Set(['admin', 'ceo', 'coo', 'cto', 'cmo']);
const isAdmin = (role) => ADMIN_ROLES.has(role);

const departmentMap = {
  commercial: '商务',
  operation: '产运',
  rd: '研发',
  business: '商务',
  product: '产运',
  '商务部': '商务',
  '产运部': '产运',
  '研发部': '研发',
};

const getDepartmentLabel = (department) => departmentMap[department] || department || '-';

const getErrorMessage = async (res, fallback) => {
  try {
    const data = await res.json();
    return data?.error || fallback;
  } catch {
    return fallback;
  }
};

export default function WeeklyReports() {
  const screens = useBreakpoint();
  const isMobile = !screens.md;
  const { user: currentUser } = useAuth();
  const [reports, setReports] = useState([]);
  const [writers, setWriters] = useState([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [writerModalVisible, setWriterModalVisible] = useState(false);
  const [filterDrawerVisible, setFilterDrawerVisible] = useState(false);
  const [drawerVisible, setDrawerVisible] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null);
  const [form] = Form.useForm();

  // 筛选
  const [filters, setFilters] = useState({
    week_start: '',
    department: '',
  });

  useEffect(() => {
    fetchReports();
  }, [filters]);

  const fetchReports = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (filters.week_start) params.append('week_start', filters.week_start);
      if (filters.department) params.append('department', filters.department);

      const res = await fetch(`/api/weekly-reports?${params}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      const data = await res.json();
      setReports(data);
    } catch (err) {
      message.error('加载失败');
    } finally {
      setLoading(false);
    }
  };

  const fetchWriters = async () => {
    try {
      const res = await fetch('/api/weekly-reports/writers', {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      if (!res.ok) throw new Error(await getErrorMessage(res, '加载失败'));
      const data = await res.json();
      setWriters(data);
    } catch (err) {
      message.error(err.message || '加载失败');
    }
  };

  const handleAdd = () => {
    const thisMonday = dayjs().startOf('isoWeek');
    const thisSunday = dayjs().endOf('isoWeek');

    form.resetFields();
    form.setFieldsValue({
      user_id: currentUser?.id,
      week_range: [thisMonday, thisSunday],
    });
    setModalVisible(true);
  };

  const handleEdit = (record) => {
    form.setFieldsValue({
      ...record,
      week_range: [dayjs(record.week_start), dayjs(record.week_end)],
    });
    setModalVisible(true);
  };

  const handleDelete = (id) => {
    Modal.confirm({
      title: '确认删除',
      content: '删除后无法恢复，确定要删除吗？',
      onOk: async () => {
        try {
          await fetch(`/api/weekly-reports/${id}`, {
            method: 'DELETE',
            headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
          });
          message.success('删除成功');
          fetchReports();
        } catch (err) {
          message.error('删除失败');
        }
      },
    });
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      const payload = {
        user_id: values.user_id,
        week_start: values.week_range[0].format('YYYY-MM-DD'),
        week_end: values.week_range[1].format('YYYY-MM-DD'),
        completed: values.completed,
        next_week_plan: values.next_week_plan,
        risks: values.risks,
      };

      await fetch('/api/weekly-reports', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify(payload),
      });

      message.success('保存成功');
      setModalVisible(false);
      fetchReports();
    } catch (err) {
      message.error('操作失败');
    }
  };

  const showDetail = (record) => {
    setSelectedReport(record);
    setDrawerVisible(true);
  };

  const handleManageWriters = async () => {
    await fetchWriters();
    setWriterModalVisible(true);
  };

  const toggleWriter = async (userId, currentValue) => {
    try {
      const res = await fetch(`/api/users/${userId}/weekly-report`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify({ need_weekly_report: !currentValue }),
      });
      if (!res.ok) throw new Error(await getErrorMessage(res, '更新失败'));
      message.success('更新成功');
      fetchWriters();
    } catch (err) {
      message.error(err.message || '更新失败');
    }
  };

  const columns = [
    { title: '姓名', dataIndex: 'user_name', key: 'user_name', width: 100 },
    {
      title: '部门',
      dataIndex: 'department',
      key: 'department',
      width: 100,
      render: (val) => getDepartmentLabel(val),
    },
    {
      title: '角色',
      dataIndex: 'user_role',
      key: 'user_role',
      width: 100,
      render: (val) => {
        const map = {
          admin: '管理员',
          leader: '组长',
          sales_director: '总监',
          member: '成员',
        };
        return map[val] || val;
      },
    },
    {
      title: '周期',
      key: 'week',
      width: 200,
      render: (_, record) => `${record.week_start} ~ ${record.week_end}`,
    },
    {
      title: '本周完成',
      dataIndex: 'completed',
      key: 'completed',
      width: 200,
      ellipsis: true,
      render: (val) => richTextToPlain(val) || '-',
    },
    {
      title: '下周计划',
      dataIndex: 'next_week_plan',
      key: 'next_week_plan',
      width: 200,
      ellipsis: true,
      render: (val) => richTextToPlain(val) || '-',
    },
    {
      title: '风险',
      dataIndex: 'risks',
      key: 'risks',
      width: 150,
      ellipsis: true,
      render: (val) => richTextToPlain(val) || '-',
    },
    {
      title: '操作',
      key: 'action',
      width: 150,
      fixed: 'right',
      render: (_, record) => (
        <Space size="small" onDoubleClick={(event) => event.stopPropagation()}>
          <Button type="link" size="small" onClick={(event) => { event.stopPropagation(); showDetail(record); }}>详情</Button>
          {(isAdmin(currentUser?.role) || record.user_id === currentUser?.id) && (
            <>
              <Button type="link" size="small" icon={<EditOutlined />} onClick={(event) => { event.stopPropagation(); handleEdit(record); }}>编辑</Button>
              {isAdmin(currentUser?.role) && (
                <Button type="link" size="small" danger icon={<DeleteOutlined />} onClick={(event) => { event.stopPropagation(); handleDelete(record.id); }}>删除</Button>
              )}
            </>
          )}
        </Space>
      ),
    },
  ];
  const { columns: resizableColumns, scrollX } = useResizableColumns('weekly-reports-table-columns', columns, {
    defaultWidth: 150,
    minWidths: { completed: 160, next_week_plan: 160, risks: 140, action: 120 },
  });

  const renderReportCard = (record) => (
    <List.Item style={{ padding: 0, marginBottom: 12, border: 'none' }}>
      <div
        role="button"
        tabIndex={0}
        onClick={() => showDetail(record)}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') showDetail(record);
        }}
        style={{
          width: '100%',
          padding: 14,
          border: '1px solid #f0f0f0',
          borderRadius: 12,
          background: '#fff',
          boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
          cursor: 'pointer',
        }}
      >
        <Space direction="vertical" size={10} style={{ width: '100%' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'flex-start', flexDirection: isMobile ? 'column' : 'row' }}>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 15, fontWeight: 600, color: '#1f2937', marginBottom: 4 }}>{record.user_name}</div>
              <Typography.Text type="secondary">{getDepartmentLabel(record.department)} · {record.user_role || '-'}</Typography.Text>
            </div>
            <Typography.Text type="secondary" style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
              {record.week_start}
            </Typography.Text>
          </div>

          <Typography.Text type="secondary">
            周期：{record.week_start} ~ {record.week_end}
          </Typography.Text>

          <Typography.Paragraph ellipsis={{ rows: 2, expandable: false }} style={{ marginBottom: 0 }}>
            本周完成：{richTextToPlain(record.completed) || '-'}
          </Typography.Paragraph>
          <Typography.Paragraph ellipsis={{ rows: 2, expandable: false }} style={{ marginBottom: 0 }}>
            下周计划：{richTextToPlain(record.next_week_plan) || '-'}
          </Typography.Paragraph>
          {record.risks && (
            <Typography.Paragraph ellipsis={{ rows: 2, expandable: false }} style={{ marginBottom: 0 }}>
              风险与问题：{richTextToPlain(record.risks)}
            </Typography.Paragraph>
          )}

          <Space size="small" wrap direction={isMobile ? 'vertical' : 'horizontal'} style={{ width: isMobile ? '100%' : undefined }}>
            <Button
              type={isMobile ? 'default' : 'link'}
              size="small"
              style={{ width: isMobile ? '100%' : undefined }}
              onClick={(event) => {
                event.stopPropagation();
                showDetail(record);
              }}
            >
              详情
            </Button>
            {(isAdmin(currentUser?.role) || record.user_id === currentUser?.id) && (
              <Button
                type={isMobile ? 'default' : 'link'}
                size="small"
                icon={<EditOutlined />}
                style={{ width: isMobile ? '100%' : undefined }}
                onClick={(event) => {
                  event.stopPropagation();
                  handleEdit(record);
                }}
              >
                编辑
              </Button>
            )}
            {isAdmin(currentUser?.role) && (
              <Button
                type={isMobile ? 'default' : 'link'}
                size="small"
                danger
                icon={<DeleteOutlined />}
                style={{ width: isMobile ? '100%' : undefined }}
                onClick={(event) => {
                  event.stopPropagation();
                  handleDelete(record.id);
                }}
              >
                删除
              </Button>
            )}
          </Space>
        </Space>
      </div>
    </List.Item>
  );

  const writerColumns = [
    { title: '姓名', dataIndex: 'display_name', key: 'display_name', width: 120 },
    {
      title: '部门',
      dataIndex: 'department',
      key: 'department',
      width: 100,
      render: (val) => getDepartmentLabel(val),
    },
    {
      title: '角色',
      dataIndex: 'role',
      key: 'role',
      width: 100,
      render: (val) => {
        const map = { leader: '组长', sales_director: '总监', member: '成员' };
        return map[val] || val;
      },
    },
    {
      title: '周报状态',
      dataIndex: 'need_weekly_report',
      key: 'need_weekly_report',
      width: 120,
      render: (val, record) => {
        if (['leader', 'sales_director'].includes(record.role)) {
          return <Tag color="blue">默认需要</Tag>;
        }
        return val ? <Tag color="green">需要</Tag> : <Tag>不需要</Tag>;
      },
    },
    {
      title: '操作',
      key: 'action',
      width: 100,
      render: (_, record) => {
        if (['leader', 'sales_director'].includes(record.role)) {
          return <span style={{ color: '#999' }}>-</span>;
        }
        return (
          <Button
            type="link"
            size="small"
            onClick={() => toggleWriter(record.id, record.need_weekly_report)}
          >
            {record.need_weekly_report ? '取消' : '指定'}
          </Button>
        );
      },
    },
  ];

  const renderWriterCard = (record) => {
    const fixedRequired = ['leader', 'sales_director'].includes(record.role);
    const roleMap = { leader: '组长', sales_director: '总监', member: '成员' };
    return (
      <List.Item style={{ padding: 0, marginBottom: 12, border: 'none' }}>
        <div
          style={{
            width: '100%',
            padding: 14,
            border: '1px solid #f0f0f0',
            borderRadius: 12,
            background: '#fff',
            boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
          }}
        >
          <Space direction="vertical" size={10} style={{ width: '100%' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'flex-start' }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 15, fontWeight: 600, color: '#1f2937' }}>{record.display_name}</div>
                <Typography.Text type="secondary">
                  {getDepartmentLabel(record.department)} · {roleMap[record.role] || record.role}
                </Typography.Text>
              </div>
              {fixedRequired ? (
                <Tag color="blue">默认需要</Tag>
              ) : record.need_weekly_report ? (
                <Tag color="green">需要</Tag>
              ) : (
                <Tag>不需要</Tag>
              )}
            </div>
            {!fixedRequired && (
              <Button
                size="small"
                style={{ width: '100%' }}
                onClick={() => toggleWriter(record.id, record.need_weekly_report)}
              >
                {record.need_weekly_report ? '取消周报' : '指定周报'}
              </Button>
            )}
          </Space>
        </div>
      </List.Item>
    );
  };

  // 快速选择周
  const quickWeeks = [];
  for (let i = 0; i < 8; i++) {
    const monday = dayjs().subtract(i, 'week').startOf('isoWeek');
    quickWeeks.push({
      label: i === 0 ? '本周' : `${i}周前`,
      value: monday.format('YYYY-MM-DD'),
    });
  }
  const activeFilterCount = Object.values(filters).filter(Boolean).length;
  const filterControls = (
    <Space direction={isMobile ? 'vertical' : 'horizontal'} style={{ width: isMobile ? '100%' : undefined }} wrap>
      <Select
        placeholder="选择周"
        style={{ width: isMobile ? '100%' : 200 }}
        allowClear
        value={filters.week_start || undefined}
        onChange={(val) => setFilters({ ...filters, week_start: val || '' })}
      >
        {quickWeeks.map((w) => (
          <Option key={w.value} value={w.value}>{w.label} ({w.value})</Option>
        ))}
      </Select>
      <Select
        placeholder="部门"
        style={{ width: isMobile ? '100%' : 150 }}
        allowClear
        value={filters.department || undefined}
        onChange={(val) => setFilters({ ...filters, department: val || '' })}
      >
        <Option value="commercial">商务</Option>
        <Option value="operation">产运</Option>
        <Option value="rd">研发</Option>
      </Select>
    </Space>
  );

  return (
    <div style={{ padding: isMobile ? 12 : 24 }}>
      <div style={{ marginBottom: 16, display: 'flex', gap: 12, alignItems: isMobile ? 'stretch' : 'center', flexDirection: isMobile ? 'column' : 'row', flexWrap: 'wrap' }}>
        {!isMobile && filterControls}
        {isMobile && (
          <Button icon={<FilterOutlined />} onClick={() => setFilterDrawerVisible(true)} style={{ width: '100%' }}>
            筛选{activeFilterCount > 0 ? ` (${activeFilterCount})` : ''}
          </Button>
        )}
        <div style={{ flex: 1 }} />
        {isAdmin(currentUser?.role) && (
          <Button icon={<SettingOutlined />} onClick={handleManageWriters} style={{ width: isMobile ? '100%' : undefined }}>
            管理周报人员
          </Button>
        )}
        <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd} style={{ width: isMobile ? '100%' : undefined }}>
          写周报
        </Button>
      </div>

      {isMobile ? (
        <List
          loading={loading}
          dataSource={reports}
          locale={{ emptyText: '暂无周报数据' }}
          pagination={{ pageSize: 20, showSizeChanger: false, simple: isMobile }}
          renderItem={renderReportCard}
        />
      ) : (
        <Table
          columns={resizableColumns}
          dataSource={reports}
          rowKey="id"
          loading={loading}
          components={resizableTableComponents}
          scroll={{ x: scrollX }}
          tableLayout="fixed"
          pagination={{ pageSize: 20 }}
          onRow={(record) => ({
            onDoubleClick: () => showDetail(record),
            style: { cursor: 'pointer' },
          })}
        />
      )}

      <Modal
        title="周报"
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={handleSubmit}
        width={isMobile ? '100%' : 700}
        style={isMobile ? { top: 0, maxWidth: '100%', paddingBottom: 0 } : undefined}
        styles={isMobile ? { body: { maxHeight: 'calc(100vh - 150px)', overflowY: 'auto' } } : undefined}
        okText="保存"
        cancelText="取消"
      >
        <Form form={form} layout="vertical">
          <Form.Item name="user_id" label="用户" hidden>
            <Input />
          </Form.Item>
          <Form.Item name="week_range" label="周期" rules={[{ required: true, message: '请选择周期' }]}>
            <RangePicker style={{ width: '100%' }} />
          </Form.Item>
          <Form.Item name="completed" label="本周完成" rules={[{ required: true, message: '请填写本周完成内容' }]} valuePropName="value" trigger="onChange">
            <RichTextEditor placeholder="本周完成的主要工作..." minHeight={140} />
          </Form.Item>
          <Form.Item name="next_week_plan" label="下周计划" rules={[{ required: true, message: '请填写下周计划' }]} valuePropName="value" trigger="onChange">
            <RichTextEditor placeholder="下周计划的主要工作..." minHeight={140} />
          </Form.Item>
          <Form.Item name="risks" label="风险与问题" valuePropName="value" trigger="onChange">
            <RichTextEditor placeholder="遇到的风险、问题或需要协调的事项..." minHeight={120} />
          </Form.Item>
        </Form>
      </Modal>

      <Drawer
        title="筛选周报"
        placement="right"
        width="100%"
        open={filterDrawerVisible}
        onClose={() => setFilterDrawerVisible(false)}
        footer={
          <Space style={{ width: '100%', justifyContent: 'space-between' }}>
            <Button onClick={() => setFilters({ week_start: '', department: '' })}>重置</Button>
            <Button type="primary" onClick={() => setFilterDrawerVisible(false)}>完成</Button>
          </Space>
        }
      >
        {filterControls}
      </Drawer>

      <Modal
        title="管理周报人员"
        open={writerModalVisible}
        onCancel={() => setWriterModalVisible(false)}
        footer={[
          <Button key="close" onClick={() => setWriterModalVisible(false)}>关闭</Button>,
        ]}
        width={isMobile ? '100%' : 700}
        style={isMobile ? { top: 0, maxWidth: '100%', paddingBottom: 0 } : undefined}
        styles={isMobile ? { body: { maxHeight: 'calc(100vh - 150px)', overflowY: 'auto' } } : undefined}
      >
        <div style={{ marginBottom: 12, color: '#666', fontSize: 13 }}>
          组长和总监默认需要写周报。老板可以指定普通成员写周报。
        </div>
        {isMobile ? (
          <List
            dataSource={writers}
            rowKey="id"
            locale={{ emptyText: '暂无人员' }}
            renderItem={renderWriterCard}
          />
        ) : (
          <Table
            columns={writerColumns}
            dataSource={writers}
            rowKey="id"
            pagination={false}
            size="small"
            scroll={{ x: 520 }}
          />
        )}
      </Modal>

      <Drawer
        title="周报详情"
        placement="right"
        width={isMobile ? '100%' : 600}
        open={drawerVisible}
        onClose={() => setDrawerVisible(false)}
        styles={isMobile ? { body: { maxHeight: 'calc(100vh - 56px)', overflowY: 'auto' } } : undefined}
      >
        {selectedReport && (
          <div>
            <div style={{ marginBottom: 24 }}>
              <div style={{ color: '#999', fontSize: 13, marginBottom: 4 }}>姓名</div>
              <div style={{ fontSize: 15 }}>{selectedReport.user_name}</div>
            </div>
            <div style={{ marginBottom: 24 }}>
              <div style={{ color: '#999', fontSize: 13, marginBottom: 4 }}>部门</div>
              <div style={{ fontSize: 15 }}>{getDepartmentLabel(selectedReport.department)}</div>
            </div>
            <div style={{ marginBottom: 24 }}>
              <div style={{ color: '#999', fontSize: 13, marginBottom: 4 }}>周期</div>
              <div style={{ fontSize: 15 }}>{selectedReport.week_start} ~ {selectedReport.week_end}</div>
            </div>
            <div style={{ marginBottom: 24 }}>
              <div style={{ color: '#999', fontSize: 13, marginBottom: 4 }}>本周完成</div>
              <RichTextView value={selectedReport.completed} />
            </div>
            <div style={{ marginBottom: 24 }}>
              <div style={{ color: '#999', fontSize: 13, marginBottom: 4 }}>下周计划</div>
              <RichTextView value={selectedReport.next_week_plan} />
            </div>
            <div style={{ marginBottom: 24 }}>
              <div style={{ color: '#999', fontSize: 13, marginBottom: 4 }}>风险与问题</div>
              <RichTextView value={selectedReport.risks} />
            </div>
          </div>
        )}
      </Drawer>
    </div>
  );
}
